// Helper functions
function getAllWords() {
    const allWords = [];
    Object.keys(ARB202_VOCABULARY).forEach(moduleKey => {
        ARB202_VOCABULARY[moduleKey].words.forEach(word => {
            allWords.push({ ...word, module: moduleKey });
        });
    });
    return allWords;
}

function getModuleWords(moduleKey) {
    return ARB202_VOCABULARY[moduleKey]?.words || [];
}

function getModuleInfo(moduleKey) {
    return ARB202_VOCABULARY[moduleKey]?.name || null;
}

function getWordCount() {
    return getAllWords().length;
}

function getModuleCount() {
    return Object.keys(ARB202_VOCABULARY).length;
}

